import * as THREE from 'three';
import { describe, expect, it } from 'vitest';
import type { HazardObstacle, MovingObstacle, ObstacleDescriptor, StaticObstacle } from '../courses/types';
import { DynamicObstacle } from './DynamicObstacle';
import { ObstacleManager } from './ObstacleManager';
import { motionPose, normalizeAxis, quatFromAxisAngle } from './motion';
import type { ObstacleBody, ObstacleBodyOptions, ObstaclePhysicsAdapter, ObstaclePose } from './types';

interface BodyRecord {
  id: string;
  options: ObstacleBodyOptions;
  poses: ObstaclePose[];
  enabledCalls: boolean[];
  disposeCount: number;
}

class FakePhysics implements ObstaclePhysicsAdapter {
  readonly records: BodyRecord[] = [];

  createBody(descriptor: ObstacleDescriptor, pose: ObstaclePose, options: ObstacleBodyOptions): ObstacleBody {
    const record: BodyRecord = { id: descriptor.id, options, poses: [pose], enabledCalls: [], disposeCount: 0 };
    this.records.push(record);
    return {
      setPose: (next: ObstaclePose) => { record.poses.push(next); },
      setEnabled: (enabled: boolean) => { record.enabledCalls.push(enabled); },
      dispose: () => { record.disposeCount += 1; },
    };
  }

  find(id: string): BodyRecord {
    const record = this.records.find((entry) => entry.id === id);
    if (!record) throw new Error(`no body recorded for ${id}`);
    return record;
  }
}

function last<T>(items: readonly T[]): T {
  const item = items[items.length - 1];
  if (item === undefined) throw new Error('empty list');
  return item;
}

const wall: StaticObstacle = {
  id: 'wall', type: 'wall', size: { x: 4, y: 1, z: 0.4 },
  transform: { position: { x: 1, y: 0.5, z: 2 } },
};

const spinner: MovingObstacle = {
  id: 'spinner', type: 'spinner', size: { x: 3, y: 0.4, z: 0.4 },
  transform: { position: { x: 0, y: 0.3, z: 0 } },
  motion: { kind: 'rotate', axis: { x: 0, y: 1, z: 0 }, speed: 2 },
};

const water: HazardObstacle = {
  id: 'water', type: 'water', size: { x: 3, y: 0.2, z: 3 },
  transform: { position: { x: -4, y: 0, z: 0 } }, penaltyStrokes: 2,
};

describe('ObstacleManager lifecycle', () => {
  it('creates a visual and a physics body per descriptor', () => {
    const parent = new THREE.Group();
    const physics = new FakePhysics();
    const manager = new ObstacleManager({ parent, physics });

    const created = manager.load([wall, spinner, water]);

    expect(created).toHaveLength(3);
    expect(manager.count).toBe(3);
    expect(manager.ids).toEqual(['wall', 'spinner', 'water']);
    expect(parent.children).toHaveLength(3);
    expect(physics.find('wall').options).toMatchObject({ kinematic: false, sensor: false, restitution: 0.45 });
    expect(physics.find('spinner').options.kinematic).toBe(true);
    expect(physics.find('water').options.sensor).toBe(true);
    expect(manager.get('wall')?.visual?.position.toArray()).toEqual([1, 0.5, 2]);
  });

  it('replaces an obstacle registered under an existing id', () => {
    const parent = new THREE.Group();
    const physics = new FakePhysics();
    const manager = new ObstacleManager({ parent, physics });

    const first = manager.add(wall);
    const second = manager.add({ ...wall, transform: { position: { x: 9, y: 0, z: 9 } } });

    expect(manager.count).toBe(1);
    expect(parent.children).toHaveLength(1);
    expect(first.disposed).toBe(true);
    expect(second.basePose.position.x).toBe(9);
  });

  it('advances moving obstacles only and pushes poses to physics', () => {
    const physics = new FakePhysics();
    const manager = new ObstacleManager({ physics, visuals: null });
    manager.load([wall, spinner]);

    manager.update(0.25);
    manager.update(0.25);

    const expected = quatFromAxisAngle({ x: 0, y: 1, z: 0 }, 1);
    const rotation = manager.get('spinner')?.pose.rotation;
    expect(rotation?.y).toBeCloseTo(expected.y, 10);
    expect(rotation?.w).toBeCloseTo(expected.w, 10);
    expect(manager.get('spinner')?.elapsedSeconds).toBeCloseTo(0.5, 10);
    expect(physics.find('spinner').poses).toHaveLength(3);
    expect(physics.find('wall').poses).toHaveLength(2);
  });

  it('clamps oversized frame deltas and restores the base pose on reset', () => {
    const manager = new ObstacleManager({ visuals: null });
    const obstacle = manager.add(spinner);

    manager.update(5);
    expect(obstacle.elapsedSeconds).toBeCloseTo(0.1, 10);

    manager.reset();
    expect(obstacle.elapsedSeconds).toBe(0);
    expect(obstacle.pose.rotation).toEqual({ x: 0, y: 0, z: 0, w: 1 });
  });

  it('honours the enabled flag for visuals and colliders', () => {
    const parent = new THREE.Group();
    const physics = new FakePhysics();
    const manager = new ObstacleManager({ parent, physics });
    const obstacle = manager.add({ ...spinner, enabled: false });

    expect(obstacle.enabled).toBe(false);
    expect(obstacle.visual?.visible).toBe(false);
    expect(last(physics.find('spinner').enabledCalls)).toBe(false);

    manager.update(0.5);
    expect(obstacle.elapsedSeconds).toBe(0);

    obstacle.setEnabled(true);
    expect(obstacle.visual?.visible).toBe(true);
    expect(last(physics.find('spinner').enabledCalls)).toBe(true);
    manager.update(0.5);
    expect(obstacle.elapsedSeconds).toBeCloseTo(0.5, 10);
  });

  it('disposes body and visual exactly once when removed', () => {
    const parent = new THREE.Group();
    const physics = new FakePhysics();
    const manager = new ObstacleManager({ parent, physics });
    const obstacle = manager.add(wall);

    expect(manager.remove('wall')).toBe(true);
    expect(manager.remove('wall')).toBe(false);
    obstacle.dispose();

    expect(physics.find('wall').disposeCount).toBe(1);
    expect(obstacle.disposed).toBe(true);
    expect(obstacle.visual?.parent).toBeNull();
    expect(parent.children).toHaveLength(0);
    expect(manager.count).toBe(0);
  });

  it('tears down every obstacle on dispose and refuses further additions', () => {
    const parent = new THREE.Group();
    const physics = new FakePhysics();
    const manager = new ObstacleManager({ parent, physics });
    manager.load([wall, spinner, water]);

    manager.dispose();
    manager.dispose();
    manager.update(0.5);

    expect(manager.count).toBe(0);
    expect(parent.children).toHaveLength(0);
    expect(physics.records.map((record) => record.disposeCount)).toEqual([1, 1, 1]);
    expect(() => manager.add(wall)).toThrow(/disposed/);
  });

  it('works headless without visuals or physics', () => {
    const obstacle = new DynamicObstacle(spinner);
    obstacle.update(0.05);
    expect(obstacle.animated).toBe(true);
    expect(obstacle.pose.rotation.w).toBeCloseTo(Math.cos(0.05), 10);
    obstacle.dispose();
    obstacle.update(0.05);
    expect(obstacle.elapsedSeconds).toBeCloseTo(0.05, 10);
  });
});

describe('obstacle motion math', () => {
  it('falls back to the up axis for degenerate axes', () => {
    expect(normalizeAxis({ x: 0, y: 0, z: 0 })).toEqual({ x: 0, y: 1, z: 0 });
    expect(normalizeAxis({ x: 0, y: 0, z: 4 })).toEqual({ x: 0, y: 0, z: 1 });
  });

  it('oscillates translating platforms along the normalized axis', () => {
    const base: ObstaclePose = { position: { x: 0, y: 1, z: 0 }, rotation: { x: 0, y: 0, z: 0, w: 1 } };
    const pose = motionPose(
      { kind: 'translate', axis: { x: 0, y: 0, z: 3 }, speed: 1, distance: 2, phase: Math.PI / 2 },
      base,
      0,
    );

    expect(pose.position.z).toBeCloseTo(2, 10);
    expect(pose.position.x).toBe(0);
    expect(pose.rotation).toEqual(base.rotation);
  });
});
